const norm=s=>String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'')
 .toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
/** FireRed level at which a move can really be learned. null = not in level-up set.
 * An evolved Pokémon retains move knowledge from its ancestral forms.
 * Level-1 species-only moves on evolutions cannot arrive before evolution.
 */
export function frlgUnlockLevel(species,move){
 const key=norm(move);let id=norm(species),min=null,guard=0;
 const stage=KANTO_LEVEL_EVOLUTIONS[id]?.[1]||1;
 while(FRLG_LEVEL_UP[id]&&guard++<5){
  const n=FRLG_LEVEL_UP[id][key];
  if(Number.isInteger(n)){
   const ready=id===norm(species)?Math.max(n,stage):n;
   min=min===null?ready:Math.min(min,ready);
  }
  id=KANTO_LEVEL_EVOLUTIONS[id]?.[0];
  if(!id)break;
 }
 return min;
}
export function frlgEvolutionLevel(id){
 return KANTO_LEVEL_EVOLUTIONS[norm(id)]?.[1]||1;
}
export function frlgMachineCompatible(id,move){
 return (FRLG_MACHINES[norm(id)]||[]).includes(norm(move));
}
export function frlgKnownMoves(species){
 let id=norm(species),guard=0;const all=new Map();
 while(FRLG_LEVEL_UP[id]&&guard++<5){
  for(const [name,level] of Object.entries(FRLG_LEVEL_UP[id]))
   all.set(name,Math.min(all.get(name)??Infinity,level));
  id=KANTO_LEVEL_EVOLUTIONS[id]?.[0];
  if(!id)break;
 }
 return [...all.keys()];
}
